-- =====================================================================
-- TÉCNICA · FASE 1 · EVENTOS: ORIGEN Y TUBOS · 80 — VERIFICACIÓN DE SOLO LECTURA (una sola consulta; apta para el editor SQL web). Todas las filas deben decir OK.
-- Nota: después de este paquete, la fila de la huella del conjunto de la verificación de las descargas de Distribución deja de valer.
-- =====================================================================
select k, v from (
  select 1 as o, '01 las 2 RPC nuevas: security definer, search_path fijo, solo service_role' as k,
         case when (select count(*) from pg_proc p where p.oid in (to_regprocedure('public.geoportal_redes_evento_causal_fijar(text,text,text,boolean,text)'), to_regprocedure('public.geoportal_redes_tubo_sectores_fijar(text,text,text[],text)'))
                     and p.prosecdef and p.proconfig is not null and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute')
                     and not has_function_privilege('authenticated', p.oid, 'execute') and not exists (select 1 from aclexplode(p.proacl) x where x.grantee = 0)) = 2 then 'OK' else 'MAL' end as v
  union all select 2, '02 ninguna función interna de redes la ejecuta la API',
         case when not exists (select 1 from pg_proc p where p.pronamespace = 'redes'::regnamespace
                                and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute') or has_function_privilege('service_role', p.oid, 'execute'))) then 'OK' else 'MAL' end
  union all select 3, '03 huellas md5: las 11 reemplazadas, las 5 nuevas y el conjunto de redes',
         case when (select count(*) from (values ('redes.f_evento_zona(jsonb)', '795f3c6c45b34306060d375ebe1f370d'), ('public.geoportal_redes_evento_declarar(text,jsonb)', 'fdf51a96463dac4088a66632fb926d06'), ('public.geoportal_redes_evento_catalogo(text)', '845a7401e73af489e42e716241bbd06f'), ('redes.f_evento_json(bigint,boolean)', '45f59666e3984baa767aa251e20ef79a'), ('public.geoportal_redes_planta_sectores_fijar(text,text,text[],text)', '147efbf990088feecd07994db03732aa'), ('redes.f_rep_columnas(text)', 'a6955a401c14a8692d68402294db810e'), ('redes.f_rep_eventos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'bef95e9511f4eaf360ede1023e8c40a4'), ('redes.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', '41c7b3680290ba3bcfe7a98cae9fe7dc'), ('tecnica.f_rep_columnas(text,jsonb)', '433cc539c24e1e14b07f96d79e974f65'), ('tecnica.f_rep_eventos_planta(jsonb,boolean,timestamp with time zone,text,integer)', '1f3ac41ec397b2ce20d0d818c63b0b15'), ('tecnica.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', 'fe08987ea0b82be59420fc5d964459ff')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 11
               and (select count(*) from (values ('redes.f_evento_origen(bigint)', '81107c71dfa94d8c79fef3ca595e7788'), ('redes.f_tubo_zona(text[])', 'a15f2de42924d7c6c0da5f1f73ea880e'), ('redes.f_tubo_es_distribucion()', '9d5b37643892051a53684a1cdfd82e4c'), ('public.geoportal_redes_evento_causal_fijar(text,text,text,boolean,text)', '5330bd20fe560e627d4a8532dd7e11b2'), ('public.geoportal_redes_tubo_sectores_fijar(text,text,text[],text)', '03657c4afcbcdb5374bb5812103439b6')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 5
               and (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p
                     where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) = '1ba192724c2fddcf321104700829f3cc' then 'OK' else 'MAL' end
  union all select 4, '04 no se tocó evento_contrato, el aviso, el SCRR, los disparadores, el bot ni las demás rutas de eventos (31 funciones)',
         case when (select count(*) from (values ('geoportal_redes_evento_anular(text,text,text)', '8947de32c9f76c9bfc937a31e8bf2c39'), ('geoportal_redes_evento_asociar(text,text,text,text,text)', 'd97df5946041079714a86de12e1d1902'), ('geoportal_redes_evento_cerrar(text,text,text,text)', '1ae6ea7e5c0c5f71b5d41f752775f343'), ('geoportal_redes_evento_contrato(text,text)', 'f82b45906c62feca8b431020284e8bbf'), ('geoportal_redes_evento_desasociar(text,text,text,text,text)', 'cf6f1f7a378e8ab653be26aa9a78a4ee'), ('geoportal_redes_evento_regreso(text,text,text,text)', 'daa542d7d0b0f8cbb09c4f4429fbfd6a'), ('geoportal_redes_evento_tipo_fijar(text,text,text,boolean,text,text,text)', '72a0f1537529089418bd981a30f2fdca'), ('geoportal_redes_evento_vista_previa(text,jsonb)', 'cb22112ec60088390648e3394f1376d7'), ('geoportal_redes_evento(text,text)', 'e1c60d1fdc53332d64db9360ed164461'), ('geoportal_redes_eventos_vigentes(text)', '30d3b3306038af969a1e7e1b75e6f5ef'), ('geoportal_redes_eventos(text,text,integer)', '5b6e1f23c3985e69cfe4908dc3752b8a'), ('geoportal_redes_reporte_iniciar(text,text,jsonb,text,boolean,text)', '05ee00808781f3af88db3d3a57c68f22'), ('geoportal_redes_reporte_pagina(text,bigint,text,integer)', '5e55735ae8f7ad024627f1393aedefdd'), ('geoportal_redes_reporte_sectores(text)', 'b4c7e051d0f41881fc24550a7297f538'), ('redes.f_evento_abierto(text,text,text)', '59df33f21167b73cbc9a5049b505859e'), ('redes.f_evento_autorizar(text,text)', '1c1dc3406cf363dbe6c7a6de06e12954'), ('redes.f_evento_candidatos(geometry,boolean,timestamp with time zone,uuid)', 'dc09e88af2c5c2daa62f2c53fa8ee842'), ('redes.f_evento_contratos(geometry,boolean,boolean)', '8dafa57412c9b41aca0a0e3652f3bf2a'), ('redes.f_evento_franja(text,timestamp with time zone,text,timestamp with time zone)', 'fb9de8c4ada4a35de44889aea9f17b62'), ('redes.f_evento_marcar(bigint[],text,text,text)', 'f067be6b5b0344e0d9c044f8ade679de'), ('redes.f_evento_reportes(bigint)', 'e9d6c5b2d72868e188e2bc5eeda47ddd'), ('redes.f_evento_tg_bot()', '857c47e052a5204c1c437c07d4cd77d1'), ('redes.f_evento_tg_campo()', '8a755c25a340e331b233ccadf99bb099'), ('redes.f_evento_tg_dano()', '430048038207e8bcfeedbf537e75faf8'), ('redes.f_evento_tg_l116()', 'a3959ab3a96e37539fd6507cddc3e075'), ('redes.f_eventos_abiertos()', '2d265a26461ea19a01e9a81bb927b120'), ('redes.f_eventos_para_avisos(timestamp with time zone)', '755cc3b1a15fbd9c82fd34991a97216a'), ('redes.f_reporte_externo_recibir_evento(jsonb)', '92be46589b80d60ce38139e3fe44550d'), ('redes.f_sector_de(geometry)', '455378c9b8cf43343ff821a2896eae37'), ('redes.f_sin_agua_para_avisos(timestamp with time zone,numeric)', '6a370c60ddcc409b06104f599110915a'), ('tecnica.f_avisos(boolean,boolean,timestamp with time zone)', 'aaa81ee57ec79080b9e76213ecea006c')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 31 then 'OK' else 'MAL' end
  union all select 5, '05 pg-safeupdate: ninguna función con DELETE o UPDATE sin WHERE', coalesce((select 'MAL: ' || string_agg(distinct funcion, ', ') from redes.f_funciones_sin_where()), 'OK')
  union all select 6, '06 las 6 tablas nuevas: RLS y sin permisos para la API; las de hechos, solo inserción',
         case when (select count(*) from pg_class c where c.oid in ('redes.evento_causales'::regclass, 'redes.evento_causal_eventos'::regclass, 'redes.evento_causal'::regclass,
                                                                      'redes.tubo_sectores'::regclass, 'redes.tubo_sector_eventos'::regclass, 'redes.evento_tubos'::regclass)
                     and c.relrowsecurity and not has_table_privilege('anon', c.oid, 'select') and not has_table_privilege('authenticated', c.oid, 'select')
                     and not has_table_privilege('service_role', c.oid, 'select')) = 6
               and (select count(*) from pg_trigger t where t.tgname in ('t_solo_agregar', 't_solo_agregar_trunc')
                     and t.tgrelid in ('redes.evento_causal_eventos'::regclass, 'redes.evento_causal'::regclass, 'redes.tubo_sector_eventos'::regclass, 'redes.evento_tubos'::regclass)) = 8 then 'OK' else 'MAL' end
  union all select 7, '07 los sectores por planta quedaron todos inactivos, con su hecho (nada se borró)',
         case when not exists (select 1 from redes.planta_sectores where activo)
               and not exists (select distinct planta_id from redes.planta_sectores except select planta_id from redes.planta_sector_eventos where motivo = 'el sistema es único; los sectores pasan a los tubos de salida') then 'OK' else 'MAL' end
  union all select 8, '08 las 5 causales de David, activas', case when (select count(*) from redes.evento_causales where activa and codigo in ('trabajo_programado', 'parametros_entrada', 'falla_planta', 'mantenimiento_planta', 'otra')) = 5 then 'OK' else 'MAL' end
  union all select 9, 'INFO causales · tubos con sectores · eventos con causal · eventos por tubo', (select count(*) from redes.evento_causales) || ' · ' || (select count(distinct punto_id) from redes.tubo_sectores where activo)
         || ' · ' || (select count(*) from redes.evento_causal) || ' · ' || (select count(distinct evento_id) from redes.evento_tubos)
) t order by o;
